def parse_query_string(qs: str) -> dict[str, str]:
    """Parse a URL query string into a dict (later values win on duplicate keys)."""
    result: dict[str, str] = {}
    if qs.startswith('?'):
        qs = qs[1:]
    for pair in qs.split("&"):
        if not pair:
            continue
        k, *v = pair.split("=")
        result[k] = "=".join(v)
    return result

